        # Apply strong backward force to satisfy unlock condition
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)
        fx_cmd = -35.0  # Just below -34 N threshold
        fy_cmd = 50.0 * (ty - y) - 20.0 * vyd + w_comp

        # Adjust force based on speed
        if spd >= cfg["bspd"] * 0.99:
            horiz = -1.5 * vx_p
            if horiz > 0:
                horiz = 0
            fx_cmd += horiz
            fy_cmd -= 1.5 * vy_p

        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1
        if state["t"] > 60:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        # Apply forward force to move toward exit
        fx, fy = 60.0, 50.0 * (ty - y) - 20.0 * vyd + w_comp

        # Check if in exit zone
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        # Apply zero force to maintain position
        fx, fy = 0.0, w_comp

    sandbox.apply_agent_force(fx, fy)
